#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define PIN_SOIL D1
#define PIN_LED D2
#define PIN_BTN D3
#define PIN_BUZ D10

#define SCREEN_W 128
#define SCREEN_H 64
Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, -1);

const int DRY_MV = 2900;
const int WET_MV = 1400;
const int DRY_THRESH_MV = 2200;
const unsigned long DRY_BUZZ_DELAY = 30UL * 1000UL;
const unsigned long MUTE_MS = 12UL * 3600UL * 1000UL;

unsigned long drySince = 0;
unsigned long muteUntil = 0;
bool lastRaw = HIGH;
bool debounced = HIGH;
unsigned long lastDeb = 0;
unsigned long lastShow = 0;
int lastMv = 0;
int lastPct = 0;

int soilMv() { return analogReadMilliVolts(PIN_SOIL); }
int soilPct(int mv) {
  int p = (DRY_MV - mv) * 100 / (DRY_MV - WET_MV);
  if (p < 0) p = 0; if (p > 100) p = 100;
  return p;
}

void setup() {
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, LOW);
  pinMode(PIN_BUZ, OUTPUT);
  digitalWrite(PIN_BUZ, LOW);
  pinMode(PIN_BTN, INPUT_PULLUP);
  Wire.begin();
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();
  display.setTextSize(2);
  display.setTextColor(SSD1306_WHITE);
}

void loop() {
  bool raw = digitalRead(PIN_BTN);
  if (raw != lastRaw) { lastDeb = millis(); lastRaw = raw; }
  if (millis() - lastDeb > 20 && debounced != lastRaw) {
    debounced = lastRaw;
    muteUntil = millis() + MUTE_MS;
  }
  lastMv = soilMv();
  lastPct = soilPct(lastMv);
  bool dry = (lastMv > DRY_THRESH_MV);
  if (dry) { if (drySince == 0) drySince = millis(); }
  else drySince = 0;
  digitalWrite(PIN_LED, dry ? HIGH : LOW);
  bool muted = (long)(millis() - muteUntil) < 0;
  bool beep = dry && drySince && (millis() - drySince > DRY_BUZZ_DELAY) && !muted;
  digitalWrite(PIN_BUZ, beep ? HIGH : LOW);
  if (millis() - lastShow > 300) {
    lastShow = millis();
    display.clearDisplay();
    display.setCursor(0, 0);
    display.print(lastPct);
    display.print(" %");
    display.setTextSize(1);
    display.setCursor(0, 30);
    if (muted) display.print("muted");
    else display.print(dry ? "poliv!" : "ok");
    display.setCursor(0, 45);
    display.print(lastMv); display.print(" mV");
    display.setTextSize(2);
    display.display();
  }
}

